begin;
do $$ declare au uuid:=gen_random_uuid();su uuid:=gen_random_uuid();pu uuid:=gen_random_uuid();ap uuid:=gen_random_uuid();sp uuid:=gen_random_uuid();pp uuid:=gen_random_uuid();client uuid;enrollment uuid;expired uuid;renewed uuid;contact uuid;n int;t date:=(now() at time zone 'America/Sao_Paulo')::date;payload jsonb;begin
 insert into auth.users(id,email) values(au,'qa-crm-admin-'||au||'@example.invalid'),(su,'qa-crm-staff-'||su||'@example.invalid'),(pu,'qa-crm-patient-'||pu||'@example.invalid');
 insert into public.profiles(id,user_id,username,full_name,role) values(ap,au,'qa-'||au,'QA CRM admin','admin'),(sp,su,'qa-'||su,'QA CRM secretary','secretary'),(pp,pu,'qa-'||pu,'QA CRM patient','patient');
 insert into public.staff_permissions(user_id,view_crm,view_contact,complete_contacts,edit_observations) values(su,true,false,true,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',au,'role','authenticated','aal','aal1')::text,true);execute 'set local role authenticated';
 client:=public.crm_save_client(null,'QA neutral client','21999118877');
 if (select user_id from public.profiles where id=client) is not null then raise exception 'FAIL neutral created login';end if;
 begin perform public.crm_save_client(null,'QA duplicate','5521999118877');raise exception 'FAIL duplicate phone accepted';exception when raise_exception then if sqlerrm like 'FAIL%' then raise;end if;end;
 enrollment:=public.crm_save_enrollment(null,client,'journey',t-15,t+75,false,2,'QA sensitive notes','active',70,170);
 select count(*) into n from public.crm_contacts where enrollment_id=enrollment;
 execute 'reset role';perform public.crm_generate_contacts();execute 'set local role authenticated';
 if (select count(*) from public.crm_contacts where enrollment_id=enrollment)<>n then raise exception 'FAIL duplicate generated cycles';end if;
 payload:=public.crm_list();if not exists(select 1 from jsonb_array_elements(payload) r where r->>'id'=client::text and r->>'state'='pending') then raise exception 'FAIL weekly due purple';end if;
 contact:=public.crm_complete_contact(enrollment,'QA contacted late');
 if not exists(select 1 from public.crm_contacts where id=contact and due_on=t-1 and completed_by=ap and completed_at is not null) then raise exception 'FAIL actor/time/latest due';end if;
 if not exists(select 1 from public.crm_contacts where enrollment_id=enrollment and due_on=t-8 and status='superseded') then raise exception 'FAIL backlog not explicit';end if;
 if public.crm_complete_contact(enrollment) is not null then raise exception 'FAIL double completion';end if;
 if (select min(due_on) from public.crm_contacts where enrollment_id=enrollment and status='pending')<>t+6 then raise exception 'FAIL late contact shifted periodicity';end if;
 begin perform public.crm_save_enrollment(null,client,'legacy',t,t+180);raise exception 'FAIL overlap accepted';exception when raise_exception then if sqlerrm like 'FAIL%' then raise;end if;end;
 perform public.crm_save_enrollment(enrollment,client,'journey',t-15,t+75,true,2,'QA sensitive notes');
 if exists(select 1 from public.crm_contacts where enrollment_id=enrollment and status='pending' and due_on<t) then raise exception 'FAIL nanny generated past duplicates';end if;
 if (select count(*) from public.crm_contacts where enrollment_id=enrollment and status='pending' and due_on between t and t+7)<>2 then raise exception 'FAIL nanny frequency';end if;
 perform public.crm_save_enrollment(enrollment,client,'journey',t-15,t+75,false,6,'QA sensitive notes');
 if (select contacts_per_week from public.crm_enrollments where id=enrollment)<>1 then raise exception 'FAIL deactivate nanny frequency';end if;
 if (select min(due_on) from public.crm_contacts where enrollment_id=enrollment and status='pending')<>t+6 then raise exception 'FAIL restored anchored weekly';end if;
 if not exists(select 1 from public.clinical_records r where r.patient_id=client and r.kind='assessment' and r.payload->>'weight_kg'='70') then raise exception 'FAIL initial assessment';end if;
 expired:=public.crm_save_enrollment(null,pp,'single',t-30,t);
 if not exists(select 1 from jsonb_array_elements(public.crm_list())r where r->>'id'=pp::text and r->>'state'='expired') then raise exception 'FAIL red priority at expiry date';end if;
 begin perform public.crm_complete_contact(expired);raise exception 'FAIL completed expired contact';exception when raise_exception then if sqlerrm like 'FAIL%' then raise;end if;end;
 renewed:=public.crm_save_enrollment(null,pp,'legacy',t,t+180);
 if (select count(*) from public.crm_enrollments where patient_id=pp)<>2 or (select status from public.crm_enrollments where id=expired)<>'closed' then raise exception 'FAIL renewal history';end if;
 if (select ends_on from public.care_attention() where patient_id=pp)<>t+180 then raise exception 'FAIL clinical screen out of sync with renewal';end if;
 perform public.crm_save_enrollment(renewed,pp,'legacy',t,t+180,false,1,'','closed');
 if (select ends_on from public.care_attention() where patient_id=pp) is not null then raise exception 'FAIL treated period still showing expiry alert';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',su,'role','authenticated','aal','aal1')::text,true);
 payload:=public.crm_profile(client);
 if payload->'client'->>'phone' is not null or payload->'client'->>'username' is not null then raise exception 'FAIL restricted phone/login leaked';end if;
 if exists(select 1 from public.profiles where id=client) or exists(select 1 from public.clinical_records where patient_id=client) or exists(select 1 from public.crm_enrollments where patient_id=client) then raise exception 'FAIL direct staff clinical reads';end if;
 perform public.crm_save_observations(enrollment,'QA staff observation');
 begin perform public.crm_save_client(client,'Unauthorized edit','21999118877');raise exception 'FAIL staff client write';exception when insufficient_privilege then null;end;
 begin perform public.crm_save_enrollment(enrollment,client,'journey',t-15,t+75);raise exception 'FAIL staff enrollment write';exception when insufficient_privilege then null;end;
 begin perform public.crm_update_staff(su,'Escalated','{"manage_clients":true}');raise exception 'FAIL staff self escalation';exception when insufficient_privilege then null;end;
 execute 'reset role';insert into auth.mfa_factors(id,user_id,factor_type,status,created_at,updated_at) values(gen_random_uuid(),su,'totp','verified',now(),now());execute 'set local role authenticated';
 begin perform public.crm_list();raise exception 'FAIL staff MFA bypass';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',su,'role','authenticated','aal','aal2')::text,true);perform public.crm_list();
 perform set_config('request.jwt.claims',jsonb_build_object('sub',au,'role','authenticated','aal','aal1')::text,true);perform public.crm_update_staff(su,'QA staff renamed','{"enabled":false,"view_crm":true,"complete_contacts":true}');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',su,'role','authenticated','aal','aal2')::text,true);
 begin perform public.crm_list();raise exception 'FAIL disabled staff access';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',pu,'role','authenticated','aal','aal1')::text,true);
 begin perform public.crm_list();raise exception 'FAIL patient CRM read';exception when insufficient_privilege then null;end;
 begin perform public.crm_profile(client);raise exception 'FAIL patient observations read';exception when insufficient_privilege then null;end;
 begin perform public.crm_complete_contact(enrollment);raise exception 'FAIL patient completion';exception when insufficient_privilege then null;end;
 if exists(select 1 from public.crm_contacts) or exists(select 1 from public.crm_audit) then raise exception 'FAIL patient table leakage';end if;
 execute 'reset role';
end $$;
select 'PASS CRM neutral clients, duplicate prevention, anchored cycles, late completion, nanny frequency, expiry priority, renewal, sensitive notes, permissions, MFA and revocation' as result;
rollback;
